package com.flippingfriend.companion;
/** Pure fail-closed binding to the same effective calibration choice used by CandidateFactory. */
final class BuyReplacementDurationCalibrationInputContextComposer {
 BuyReplacementDurationCalibrationInputContext compose(BuyReplacementRoundTripCompletionEvaluationSet s,FillCalibration calibration,boolean learningDisabled,long at){if(s==null||at<s.getEvaluatedAt()||s.getEvaluatedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty()||s.getViableCandidates()==null||s.getViableCandidates().size()!=s.getEvaluations().size())return null;for(int i=0;i<s.getEvaluations().size();i++)if(!valid(s.getEvaluations().get(i),s.getViableCandidates().get(i),s))return null;FillCalibration effective=learningDisabled||calibration==null?FillCalibration.NEUTRAL:calibration;double multiplier=effective.waitMultiplier(s.getItemId());if(!Double.isFinite(multiplier)||multiplier<0)return null;return new BuyReplacementDurationCalibrationInputContext(s,learningDisabled,multiplier,at);}
 private static boolean valid(BuyReplacementRoundTripCompletionEvaluation e,BuyReplacementSellFillViableCandidate v,BuyReplacementRoundTripCompletionEvaluationSet s){return e!=null&&v!=null&&e.getExactRemainderQuantity()==s.getExactRemainderQuantity()&&e.getBuyOffsetIndex()==v.getBuyOffsetIndex()&&Double.compare(e.getBuyOffset(),v.getBuyOffset())==0&&e.getBuyPrice()==v.getBuyPrice()&&e.getSellOffsetIndex()==v.getSellOffsetIndex()&&Double.compare(e.getSellOffset(),v.getSellOffset())==0&&e.getSellPrice()==v.getSellPrice()&&Double.compare(e.getBuyProbability(),v.getBuyProbability())==0&&Double.compare(e.getSellProbability(),v.getSellProbability())==0&&Double.compare(e.getBuyExpectedHours(),v.getBuyExpectedHours())==0&&Double.compare(e.getBuyWaitHours(),v.getBuyWaitHours())==0&&Double.compare(e.getSellExpectedHours(),v.getSellExpectedHours())==0&&Double.compare(e.getSellWaitHours(),v.getSellWaitHours())==0&&Double.compare(e.getCompletionProbability(),e.getBuyProbability()*e.getSellProbability())==0;}
}
